#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long n;
    if (!(std::cin >> n)) return 0;

    long long running = 0;
    for (long long i = 0; i < n; ++i) {
        long long v;
        if (!(std::cin >> v)) break;
        running += v;
        if (i) std::cout << ' ';
        std::cout << running;
    }
    std::cout << "\n";
    return 0;
}

